def texts(block,cls):
 return [unescape(re.sub('<[^>]+>', '', x)).strip() for x in re.findall(r'<p class="'+cls+r'"[^>]*>(.*?)</p>', block, re.S)]
def section(id):
 return source.split('id="'+id+'"',1)[1].split('</article>',1)[0]
star='<svg viewBox="-50 -50 100 100" aria-hidden="true"><path fill="#E8892A" d="M0,-50 C6,-12 12,-6 50,0 C12,6 6,12 0,50 C-6,12 -12,6 -50,0 C-12,-6 -6,-12 0,-50 Z"/></svg>'
logo='<span>pltv</span>'+star+'<span>ink</span>'
def cta(label, key, light=False):
 return f'<button class="cta {"light" if light else ""}" type="button" data-project="{key}">{label}<span class="dot" aria-hidden="true">→</span></button>'
def meta(n,title):return f'<p class="meta chapter"><span>{n:02}</span> / 05 · {title}</p>'
